class Solution {
    public int peopleAwareOfSecret(int n,int delay,int forget){
        long mod=1_000_000_007L;
        long[] learn=new long[n+1];
        learn[1]=1;
        long sharing=0;
        for(int day=2;day<=n;day++){
            if(day-delay>=1)sharing=(sharing+learn[day-delay])%mod;
            if(day-forget>=1)sharing=(sharing-learn[day-forget]+mod)%mod;
            learn[day]=sharing;
        }
        long answer=0;
        for(int day=Math.max(1,n-forget+1);day<=n;day++)answer=(answer+learn[day])%mod;
        return (int)answer;
    }
}

